/** Build-time policy for this fork. There is deliberately no online-mode toggle. */
export const OFFLINE_BUILD = true;
export const OFFLINE_APP_ORIGIN = 'https://insomnia-app.local';
export const OFFLINE_SERVICE_ERROR = 'Insomnia cloud services are disabled in this offline build.';

const networkProtocols = new Set(['http:', 'https:', 'ws:', 'wss:']);

/** Parse an administrator-managed list of EXACT origins; never accept host wildcards. */
export function parseOfflineOrigins(value: string | undefined): ReadonlySet<string> {
  if (!value) return new Set<string>();
  let input: unknown;
  try {
    input = JSON.parse(value);
  } catch {
    throw new Error('INSOMNIA_OFFLINE_BROWSER_ORIGINS must be a JSON array of exact origins.');
  }
  if (!Array.isArray(input) || input.some(item => typeof item !== 'string')) {
    throw new Error('INSOMNIA_OFFLINE_BROWSER_ORIGINS must be a JSON array of strings.');
  }
  const result = new Set<string>();
  for (const item of input as string[]) {
    let url: URL;
    try {
      url = new URL(item);
    } catch {
      throw new Error('Invalid origin in INSOMNIA_OFFLINE_BROWSER_ORIGINS.');
    }
    if (
      !networkProtocols.has(url.protocol) || /[\u0000-\u0020\u007f\\]/.test(item) ||
      !/^(?:https?|wss?):\/\//i.test(item) || url.username || url.password ||
      url.search || url.hash || (url.pathname !== '/' && url.pathname !== '') ||
      url.hostname.includes('*') || url.hostname.endsWith('.') ||
      item.trim() !== item || url.origin === 'null'
    ) {
      throw new Error('Offline browser origins must have no credentials, paths, queries, fragments or wildcards.');
    }
    result.add(url.origin);
  }
  return result;
}

/**
 * This is a Chromium/browser-request policy, NOT a firewall for Node, libcurl,
 * Git, plugins, DNS or child processes. Those need an OS/network egress policy.
 * Extra origins are explicit administrator exceptions (for example an intranet IdP).
 */
export function isOfflineBrowserUrlAllowed(
  input: string,
  extraOrigins: ReadonlySet<string> = new Set<string>(),
): boolean {
  try {
    const url = new URL(input);
    if (url.username || url.password) return false;
    if (networkProtocols.has(url.protocol)) {
      return url.origin === OFFLINE_APP_ORIGIN || extraOrigins.has(url.origin);
    }
    if (url.protocol === 'file:') {
      // A remote file://host/share is network access (SMB/UNC), not a local asset.
      const pathname = decodeURIComponent(url.pathname);
      return url.host === '' && !pathname.startsWith('//') && !pathname.includes('\\');
    }
    if (url.protocol === 'data:' || url.protocol === 'blob:') return true;
    return url.protocol === 'insomnia-templating-worker-database:';
  } catch {
    return false;
  }
}

import { models } from 'insomnia-data';

export { OFFLINE_BUILD } from './offline-policy';

export const OFFLINE_ORGANIZATION_ID = models.organization.OFFLINE_ORGANIZATION_ID;
export const OFFLINE_ORGANIZATION = models.organization.buildOfflineOrganization();
export const OFFLINE_ENTRY = `/organization/${OFFLINE_ORGANIZATION_ID}/project`;

import fs from 'node:fs';
import path from 'node:path';

import { app, session, type Session } from 'electron';

import { isDevelopment } from '../common/constants';
import { isOfflineBrowserUrlAllowed, parseOfflineOrigins } from '../common/offline-policy';

let installed = false;
let browserOrigins: ReadonlySet<string> | undefined;
const configuredSessions = new WeakSet<Session>();

export function getOfflineBrowserOrigins(): ReadonlySet<string> {
  if (browserOrigins) return browserOrigins;
  const origins = new Set(parseOfflineOrigins(process.env.INSOMNIA_OFFLINE_BROWSER_ORIGINS));
  // Match window-utils.ts: only the exact Vite loopback origin, and only in development.
  if (isDevelopment()) {
    let port = '3334';
    try {
      port = fs.readFileSync(path.resolve(__dirname, '..', '.vite-port'), 'utf8').trim();
    } catch {
      // Same fallback as the app's existing development URL.
    }
    if (!/^\d+$/.test(port) || Number(port) < 1 || Number(port) > 65535) {
      throw new Error('Invalid offline development server port.');
    }
    origins.add(`http://localhost:${Number(port)}`);
    origins.add(`ws://localhost:${Number(port)}`);
  }
  browserOrigins = origins;
  return origins;
}

export function assertOfflineBrowserRequest(url: string): void {
  if (!isOfflineBrowserUrlAllowed(url, getOfflineBrowserOrigins())) {
    // Never log a request URL: it may contain credentials, tokens or internal paths.
    throw new Error('Browser network access is disabled by the offline build policy.');
  }
}

const configureSession = (target: Session) => {
  if (configuredSessions.has(target)) return;
  configuredSessions.add(target);
  const origins = getOfflineBrowserOrigins();
  target.webRequest.onBeforeRequest({ urls: ['<all_urls>'] }, (details, callback) => {
    callback({ cancel: !isOfflineBrowserUrlAllowed(details.url, origins) });
  });
  target.setSpellCheckerEnabled(false);
  // No implicit OS/PAC discovery in Chromium. Explicit API-request proxies are handled
  // by Insomnia's native request engine, which is intentionally not monkey-patched here.
  void target.setProxy({ mode: 'direct' }).catch(() => {
    console.warn('[offline] Could not configure the Chromium direct-proxy policy.');
  });
};

/** Install before registerInsomniaProtocols and before any windows are created. */
export function installOfflineNetworkPolicy(): void {
  if (installed) return;
  getOfflineBrowserOrigins(); // Validate administrator configuration before continuing startup.
  installed = true;
  app.on('session-created', configureSession);
  if (app.isReady()) {
    configureSession(session.defaultSession);
  } else {
    app.once('ready', () => configureSession(session.defaultSession));
  }
}

/** Help/marketing links must not hand URLs to a separately network-enabled browser. */
export async function openOfflineExternal(_url: string): Promise<void> {
  console.info('[offline] Opening an external browser is disabled in this build.');
}
